# syntax=docker/dockerfile:1
# The agent is a Node app and the shell base ships no Node, so the
# overlay carries the node binary plus the globally installed package.
# dhi.io/node:24-debian13-dev is the hardened Node image: debian13 is
# trixie, matching the glibc floor of the bases these examples compose
# onto, and the -dev variant is the one carrying npm and a shell.
#
# --omit=optional drops the SDK's vendored native claude binary (shipped
# as platform-specific optional deps of @anthropic-ai/claude-agent-sdk).
# It is dead weight here — the wrapper points the adapter at the claude
# the composition installs — and omitting it keeps one claude in the
# sandbox: without the binary present the adapter cannot silently fall
# back to a second, SDK-pinned version.
FROM dhi.io/node:24-debian13-dev AS build
ARG ACP_VERSION
RUN npm install -g --omit=optional --prefix /opt/claude-agent-acp \
      "@agentclientprotocol/claude-agent-acp@${ACP_VERSION}"

FROM dhi.io/debian-base:trixie-dev
COPY --from=build /usr/bin/node /usr/local/bin/node
COPY --from=build /opt/claude-agent-acp /opt/claude-agent-acp
# The adapter briefly reports "Not logged in" while its asynchronous
# account probe is still resolving. Some ACP clients treat that interim
# notification as terminal and close an otherwise healthy connection.
# The wrapper drops only those false negatives for which a synchronous
# `claude auth status` confirms a login; genuine logged-out states pass.
# It also maps legacy `session/set_model` requests to the current
# `session/set_config_option` form for clients that still send the old
# method.
#
# And it binds the adapter to the composed claude: the adapter drives
# the CLI named by CLAUDE_CODE_EXECUTABLE, which the wrapper sets per
# launch to the claude an interactive shell would run (PATH order), so
# the ACP path and `claude` are the same agent at the version this
# composition states. Not a fixed image ENV: claude-mixin installs
# /usr/local/bin/claude but the claude workload kit $HOME/.local/bin,
# and either one answers this kit's requires: ["claude"]. An explicit
# CLAUDE_CODE_EXECUTABLE still wins when it names a real binary.
# Inlined by Kit Maker (a blueprint has no build context): COPY scripts/claude-agent-acp-wrapper.mjs /usr/local/libexec/claude-agent-acp-wrapper.mjs
COPY --chmod=755 <<'KITMAKER_EOF' /usr/local/libexec/claude-agent-acp-wrapper.mjs
#!/usr/bin/env node

import { spawn, spawnSync } from "node:child_process";
import { once } from "node:events";
import { accessSync, constants, statSync } from "node:fs";
import { homedir } from "node:os";
import { delimiter, join } from "node:path";
import { createInterface } from "node:readline";

const adapter =
  "/opt/claude-agent-acp/lib/node_modules/@agentclientprotocol/claude-agent-acp/dist/index.js";

function isExecutable(path) {
  try {
    accessSync(path, constants.X_OK);
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

// The claude this composition installed, wherever its kit put it:
// claude-mixin installs /usr/local/bin/claude, the claude workload kit
// $HOME/.local/bin/claude. An explicit CLAUDE_CODE_EXECUTABLE wins when
// it exists; otherwise PATH order, so the adapter drives the same binary
// an interactive `claude` runs. The SDK's vendored binary is omitted at
// build time, so without this the adapter would find no agent at all.
function resolveClaude() {
  const fromPath = (process.env.PATH ?? "")
    .split(delimiter)
    .filter(Boolean)
    .map((dir) => join(dir, "claude"));
  const candidates = [
    process.env.CLAUDE_CODE_EXECUTABLE,
    ...fromPath,
    "/usr/local/bin/claude",
    join(homedir(), ".local/bin/claude"),
  ].filter(Boolean);
  return { found: candidates.find(isExecutable), candidates };
}

const claude = resolveClaude();
if (!claude.found) {
  console.error(
    `claude-agent-acp: no claude binary found; looked for ${[...new Set(claude.candidates)].join(", ")}`,
  );
  process.exit(127);
}
const env = { ...process.env, CLAUDE_CODE_EXECUTABLE: claude.found };

const child = spawn(process.execPath, [adapter, ...process.argv.slice(2)], {
  env,
  stdio: ["pipe", "pipe", "inherit"],
});

const exited = new Promise((resolve) => {
  child.once("error", (error) => {
    console.error(`claude-agent-acp: ${error.message}`);
    resolve({ code: 1, signal: null });
  });
  child.once("exit", (code, signal) => resolve({ code, signal }));
});

for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"]) {
  process.once(signal, () => child.kill(signal));
}

function cliIsAuthenticated() {
  const probe = spawnSync(claude.found, ["auth", "status", "--json"], {
    encoding: "utf8",
    env,
    timeout: 5_000,
  });

  if (probe.status !== 0) return false;
  try {
    return JSON.parse(probe.stdout).loggedIn === true;
  } catch {
    return false;
  }
}

function isFalseLoggedOutNotification(line) {
  try {
    const message = JSON.parse(line);
    return (
      message.method === "_auth/status_update" &&
      message.params?.authStatus?.kind === "none" &&
      cliIsAuthenticated()
    );
  } catch {
    return false;
  }
}

function translateClientMessage(line) {
  try {
    const message = JSON.parse(line);
    if (message.method !== "session/set_model") return line;

    message.method = "session/set_config_option";
    message.params = {
      sessionId: message.params?.sessionId,
      configId: "model",
      value: message.params?.modelId,
    };
    return JSON.stringify(message);
  } catch {
    return line;
  }
}

const inputLines = createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});

async function forwardInput() {
  try {
    for await (const line of inputLines) {
      const translated = translateClientMessage(line);
      if (!child.stdin.write(`${translated}\n`))
        await once(child.stdin, "drain");
    }
  } catch (error) {
    if (child.exitCode === null && child.signalCode === null) throw error;
  } finally {
    if (!child.stdin.destroyed) child.stdin.end();
  }
}

async function forwardOutput() {
  const lines = createInterface({ input: child.stdout, crlfDelay: Infinity });
  for await (const line of lines) {
    if (isFalseLoggedOutNotification(line)) continue;
    if (!process.stdout.write(`${line}\n`))
      await once(process.stdout, "drain");
  }
}

const input = forwardInput();
const output = forwardOutput();
const { code, signal } = await exited;
inputLines.close();
process.stdin.pause();
await Promise.all([input, output]);
process.exitCode = code ?? (signal ? 1 : 0);
KITMAKER_EOF
RUN chmod 0755 /usr/local/libexec/claude-agent-acp-wrapper.mjs \
 && ln -s /usr/local/libexec/claude-agent-acp-wrapper.mjs /usr/local/bin/claude-agent-acp

# syntax=docker/dockerfile:1
# The agent is a Node app and the shell base ships no Node, so the
# overlay carries the node binary plus the globally installed package.
# dhi.io/node:24-debian13-dev is the hardened Node image: debian13 is
# trixie, matching the glibc floor of the bases these examples compose
# onto, and the -dev variant is the one carrying npm and a shell.
FROM dhi.io/node:24-debian13-dev AS build
ARG ACP_VERSION
RUN npm install -g --prefix /opt/codex-acp \
      "@agentclientprotocol/codex-acp@${ACP_VERSION}"

# The adapter bundles codex as a regular dependency whose per-platform
# binaries arrive as aliased optional deps, which --omit=optional does
# NOT skip (unlike the claude adapter's vendored binary); they are
# deleted here instead. CODEX_PATH below points the adapter at the codex
# the codex-mixin kit installs, so the bundled one is dead weight — and
# with no binary present the adapter cannot silently fall back to a
# second, dependency-pinned version. The guard fails the build if a
# codex binary survives, so the property is enforced, not asserted.
RUN find /opt/codex-acp -type d -path "*/@openai/codex-*/vendor" -prune -exec rm -rf {} + \
 && ! find /opt/codex-acp -type f -name codex | grep -q .

# A subagent Codex reuses ("interacted") stays marked finished in the
# adapter, which then drops all of its work; the script reopens it, as
# the adapter already does for the older collaboration calls. It leaves
# a release that has the fix alone and fails the build on one whose code
# moved. See the script for the details.
# Inlined by Kit Maker (a blueprint has no build context): COPY scripts/patch-reused-subagents.mjs /tmp/patch-reused-subagents.mjs
COPY --chmod=755 <<'KITMAKER_EOF' /tmp/patch-reused-subagents.mjs
#!/usr/bin/env node
// Makes codex-acp show a subagent's work again when Codex reuses it.
//
// Codex reports a follow-up to a subagent that already finished as a
// `subAgentActivity` of kind "interacted". The adapter's subagent router
// reopens a finished child only for the older collaboration calls
// (sendInput, resumeAgent, followupTask); for "interacted" it keeps the
// child marked finished and drops all of its updates ("Ignoring update
// for terminal subagent"). An ACP client with subagent sessions then sees
// a wait and nothing of the work. Reopening the child on "interacted"
// announces it again (`subagent_spawned`, `<thread>:generation:N`) and
// routes its updates there, as the router already does for the older
// calls.
//
// Applied at build time to the installed bundle. A release that already
// reopens on "interacted" is left alone; one whose router no longer has
// the code this edits fails the build, so the patch is revisited rather
// than silently lost.
import { readFileSync, writeFileSync } from "node:fs";

const file = process.argv[2];
if (!file) {
  console.error("usage: patch-reused-subagents.mjs <codex-acp dist/index.js>");
  process.exit(2);
}

const source = readFileSync(file, "utf8");
const fixed = `if (hasNativeRepresentation && item.kind === "interacted") {`;
if (source.includes(fixed)) {
  console.log("codex-acp already reopens reused subagents");
  process.exit(0);
}

const anchor = `      if (hasNativeRepresentation && item.kind === "interrupted") {`;
const count = source.split(anchor).length - 1;
if (count !== 1) {
  console.error(`codex-acp: expected the subagent router's "interrupted" branch once, found it ${count} times`);
  process.exit(1);
}

const patch = `      ${fixed}
        await this.reopen(item.agentThreadId);
      }
`;
writeFileSync(file, source.replace(anchor, patch + anchor));
console.log("codex-acp patched: reused subagents are reopened");
KITMAKER_EOF
RUN node /tmp/patch-reused-subagents.mjs \
      /opt/codex-acp/lib/node_modules/@agentclientprotocol/codex-acp/dist/index.js

FROM dhi.io/debian-base:trixie-dev
COPY --from=build /usr/bin/node /usr/local/bin/node
COPY --from=build /opt/codex-acp /opt/codex-acp
RUN ln -s /opt/codex-acp/bin/codex-acp /usr/local/bin/codex-acp

# The adapter resolves the CLI it drives from CODEX_PATH first, and only
# then from its bundled @openai/codex dependency. Pinning it to the
# composed codex is what makes the ACP path and an interactive `codex`
# the same agent, at the version this composition states. Image config
# rather than a profile.d drop on purpose: an ACP client spawns the
# adapter over non-TTY stdio (`sbx exec -i`), which never sources a login
# profile but does inherit the container environment.
ENV CODEX_PATH=/usr/local/bin/codex

# v2's sandbox.image, as content. The template carries the platform floor
# and the cursor-agent install; the workload publishes it as-is. Cursor's
# installer has no version pin, so the kit's version: field is the semver
# spelling of the cursor-agent this template build carries
# (2026.10.01-e373342 is 2026.10.1). The template tag moves on every
# refresh, so the base is pinned by digest and the build asserts the
# agent it carries: otherwise a refresh would publish a different binary
# under an unchanged kit tag. Move the digest, CURSOR_AGENT_BUILD, and
# version: together.
FROM dhi.io/sbx-templates:cursor-agent-docker@sha256:a75af8edd517e5a4f3cc0986b1d451135fb090b21ac750548653c0d1227978d8
ARG CURSOR_AGENT_BUILD=2026.10.01-e373342
# A scratch HOME, so asking for the version leaves no state in the image.
RUN scratch=$(mktemp -d) \
 && got=$(HOME="$scratch" cursor-agent --version) \
 && rm -rf "$scratch" \
 && { [ "$got" = "${CURSOR_AGENT_BUILD}" ] || { echo "cursor-agent is $got, expected ${CURSOR_AGENT_BUILD}" >&2; exit 1; }; }
# v2's environment.variables. AGENT_CLI_CREDENTIAL_STORE=memory keeps
# cursor from validating a file-backed sentinel and re-prompting login;
# auth bootstraps through the environment when host OAuth creds exist.
ENV IS_SANDBOX=1 AGENT_CLI_CREDENTIAL_STORE=memory
# The ACP launcher acp@1 names: cursor-agent's ACP server keeps running
# after stdin closes, so the wrapper follows the close with SIGTERM, which
# it does stop on.
USER root
# Inlined by Kit Maker (a blueprint has no build context): COPY scripts/acp-graceful.mjs /usr/local/bin/acp-graceful
COPY --chmod=755 <<'KITMAKER_EOF' /usr/local/bin/acp-graceful
#!/usr/bin/env node
// acp-graceful <command> [args...]
//
// Runs an agent's built-in ACP server so that stdin EOF and SIGTERM both
// end it within acp@1's five-second shutdown bound, whichever of the two
// the agent itself honors. Either event closes the agent's stdin, the
// orderly stop every ACP server is built around; an agent still running
// after the grace period gets SIGTERM, then SIGKILL. Signals go to the
// agent's whole process group, because agents that re-exec themselves
// (gemini relaunches under a larger heap) would otherwise leave the real
// worker behind.
//
// stdout and stderr are inherited rather than piped, so protocol
// messages reach the host unbuffered and logs stay on stderr.

import { spawn } from "node:child_process";
import { constants } from "node:os";

const GRACE_MS = 2_000;

const [command, ...args] = process.argv.slice(2);
if (!command) {
  console.error("usage: acp-graceful <command> [args...]");
  process.exit(2);
}

const child = spawn(command, args, {
  stdio: ["pipe", "inherit", "inherit"],
  detached: true,
});

function signalGroup(signal) {
  try {
    process.kill(-child.pid, signal);
  } catch {
    // The group is already gone.
  }
}

let stopping = false;
function stop() {
  if (stopping) return;
  stopping = true;
  if (!child.stdin.destroyed) child.stdin.end();
  setTimeout(() => signalGroup("SIGTERM"), GRACE_MS).unref();
  setTimeout(() => signalGroup("SIGKILL"), 2 * GRACE_MS).unref();
}

process.stdin.pipe(child.stdin);
process.stdin.once("end", stop);
child.stdin.on("error", () => {});
for (const signal of ["SIGTERM", "SIGINT", "SIGHUP"]) process.on(signal, stop);

child.once("error", (error) => {
  console.error(`acp-graceful: ${command}: ${error.message}`);
  process.exit(127);
});
child.once("exit", (code, signal) => {
  process.exit(code ?? 128 + (constants.signals[signal] ?? 0));
});
KITMAKER_EOF
RUN chmod 0755 /usr/local/bin/acp-graceful
USER agent
WORKDIR /home/agent/workspace
# v2's sandbox.entrypoint.
ENTRYPOINT ["cursor-agent", "--yolo"]

# v2's sandbox.image, as content. The template carries the platform floor
# (node, jq for the MCP merge hook) and the gemini-cli install; the
# workload publishes it as-is, with the kit's version: field speaking for
# the artifact.
FROM dhi.io/sbx-templates:gemini-docker
# v2's environment.variables. GEMINI_SANDBOX=false: this container IS the
# sandbox; gemini must not try to nest its own.
ENV BROWSER=xdg-open DISPLAY=:0 SANDBOX=docker GEMINI_SANDBOX=false
# The ACP launcher acp@1 names: gemini's ACP mode ignores SIGTERM, so the
# wrapper turns it into the stdin close gemini does stop on.
USER root
# Inlined by Kit Maker (a blueprint has no build context): COPY scripts/acp-graceful.mjs /usr/local/bin/acp-graceful
COPY --chmod=755 <<'KITMAKER_EOF' /usr/local/bin/acp-graceful
